create trigger [trg_widgets_changes] on [widgets] after update, delete as
begin
    set nocount on;
    if exists (select 1 from inserted) and not (update([name]) or update([price])) return;
insert into widget_log (widget_id, at) select o.id, todatetimeoffset(sysutcdatetime(), 0) from deleted o;
end

create or replace function "trg_widgets_changes_fn"() returns trigger language plpgsql as $$
begin
insert into widget_log (widget_id, at) select o.id, now() from (select old."id" as "id") o;
    return null;
end
$$
